# Generated by build.py from recipe.yml for recipe ftp-handle-a-full-disk-during-upload. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'head -c 300000 /dev/urandom > big.csv'
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--allow-uploads', '--max-filesize', '100000', '--directory', 'site', '-v', '--log-file', 'surl.log', '--fault', '"out-of-space;path=/archive"', 'ftp://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -T export.csv ftp://127.0.0.1:8080/archive/2026-11-20.csv } finally { Stop-Process $server0 }
